from google.cloud import pubsub_v1
import os
import json

def publish_event(project_id: str, topic_id: str, message: dict) -> str:
    """Publishes a message to a Google Cloud Pub/Sub topic."""
    publisher = pubsub_v1.PublisherClient()
    topic_path = publisher.topic_path(project_id, topic_id)

    message_json = json.dumps(message).encode("utf-8")

    future = publisher.publish(topic_path, message_json)
    return future.result()

if __name__ == "__main__":
    PROJECT_ID = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    TOPIC_ID = os.getenv("GOOGLE_CLOUD_PUBSUB_TOPIC_ID")

    if not PROJECT_ID or not TOPIC_ID:
        print("Please set GOOGLE_CLOUD_PROJECT_ID and GOOGLE_CLOUD_PUBSUB_TOPIC_ID environment variables.")
    else:
        test_message = {"event": "test_event", "data": "Hello, Pub/Sub!"}
        message_id = publish_event(PROJECT_ID, TOPIC_ID, test_message)
        print(f"Published message with ID: {message_id}")

from google.cloud import pubsub_v1
import os

def consume_event(project_id: str, subscription_id: str) -> dict or None:
    """Consumes one message from a Google Cloud Pub/Sub subscription."""
    subscriber = pubsub_v1.SubscriberClient()
    subscription_path = subscriber.subscription_path(project_id, subscription_id)

    response = subscriber.pull(request={"subscription": subscription_path, "max_messages": 1})

    if response.received_messages:
        message = response.received_messages[0].message

        # Acknowledge the message to remove it from the subscription
        ack_ids = [response.received_messages[0].ack_id]
        subscriber.acknowledge(request={"subscription": subscription_path, "ack_ids": ack_ids})

        return {
            "data": message.data.decode("utf-8"),
            "attributes": dict(message.attributes),
            "message_id": message.message_id,
        }
    return None

if __name__ == "__main__":
    PROJECT_ID = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    SUBSCRIPTION_ID = os.getenv("GOOGLE_CLOUD_PUBSUB_SUBSCRIPTION_ID")

    if not PROJECT_ID or not SUBSCRIPTION_ID:
        print("Please set GOOGLE_CLOUD_PROJECT_ID and GOOGLE_CLOUD_PUBSUB_SUBSCRIPTION_ID environment variables.")
    else:
        message = consume_event(PROJECT_ID, SUBSCRIPTION_ID)
        if message:
            print(f"Consumed message: {message}")
        else:
            print("No messages to consume.")

from google.cloud import pubsub_v1
import os
import json

def send_to_dead_letter(project_id: str, dead_letter_topic_id: str, message: dict, original_message_id: str) -> str:
    """Sends a failed message to a designated dead-letter topic in Google Cloud Pub/Sub."""
    publisher = pubsub_v1.PublisherClient()
    dead_letter_topic_path = publisher.topic_path(project_id, dead_letter_topic_id)

    message_json = json.dumps(message).encode("utf-8")

    # Add an attribute to indicate the original message ID
    attributes = {"original_message_id": original_message_id, "failure_reason": "simulated_processing_failure"}

    future = publisher.publish(dead_letter_topic_path, message_json, **attributes)
    return future.result()

if __name__ == "__main__":
    PROJECT_ID = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    DEAD_LETTER_TOPIC_ID = os.getenv("GOOGLE_CLOUD_PUBSUB_DEAD_LETTER_TOPIC_ID")

    if not PROJECT_ID or not DEAD_LETTER_TOPIC_ID:
        print("Please set GOOGLE_CLOUD_PROJECT_ID and GOOGLE_CLOUD_PUBSUB_DEAD_LETTER_TOPIC_ID environment variables.")
    else:
        failed_message = {"event": "failed_event", "data": "This message failed processing."}
        original_id = "some-original-message-id-123"
        message_id = send_to_dead_letter(PROJECT_ID, DEAD_LETTER_TOPIC_ID, failed_message, original_id)
        print(f"Sent failed message to dead-letter topic with ID: {message_id}")

from google.cloud import pubsub_v1
import os

class PubSubClientHelper:
    def __init__(self, project_id: str):
        self.project_id = project_id
        self.publisher_client = pubsub_v1.PublisherClient()
        self.subscriber_client = pubsub_v1.SubscriberClient()

    def get_topic_path(self, topic_id: str) -> str:
        """Returns the full topic path for a given topic ID."""
        return self.publisher_client.topic_path(self.project_id, topic_id)

    def get_subscription_path(self, subscription_id: str) -> str:
        """Returns the full subscription path for a given subscription ID."""
        return self.subscriber_client.subscription_path(self.project_id, subscription_id)

    def get_publisher_client(self) -> pubsub_v1.PublisherClient:
        """Returns an initialized Pub/Sub publisher client."""
        return self.publisher_client

    def get_subscriber_client(self) -> pubsub_v1.SubscriberClient:
        """Returns an initialized Pub/Sub subscriber client."""
        return self.subscriber_client


if __name__ == "__main__":
    PROJECT_ID = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    if not PROJECT_ID:
        print("Please set GOOGLE_CLOUD_PROJECT_ID environment variable.")
    else:
        client_helper = PubSubClientHelper(PROJECT_ID)
        topic_path = client_helper.get_topic_path("my-test-topic")
        subscription_path = client_helper.get_subscription_path("my-test-subscription")
        print(f"Test Topic Path: {topic_path}")
        print(f"Test Subscription Path: {subscription_path}")

import json
from typing import Dict, Any, Optional

class PubSubMessage:
    """Represents a standardized Pub/Sub message structure."""
    def __init__(self, data: Dict[str, Any], attributes: Optional[Dict[str, str]] = None, message_id: Optional[str] = None):
        self.data = data
        self.attributes = attributes if attributes is not None else {}
        self.message_id = message_id

    def to_json(self) -> bytes:
        """Encodes the message data to JSON bytes."""
        return json.dumps(self.data).encode("utf-8")

    @classmethod
    def from_json(cls, json_data: bytes, attributes: Optional[Dict[str, str]] = None, message_id: Optional[str] = None):
        """Decodes JSON bytes into a PubSubMessage object."""
        data = json.loads(json_data.decode("utf-8"))
        return cls(data, attributes, message_id)

    def __repr__(self) -> str:
        return f"PubSubMessage(data={self.data}, attributes={self.attributes}, message_id={self.message_id})"

class PubSubBatchMessage:
    """Represents a message within a batch, including data and attributes."""
    def __init__(self, data: Dict[str, Any], attributes: Optional[Dict[str, str]] = None):
        self.data = data
        self.attributes = attributes if attributes is not None else {}

    def to_publish_format(self) -> Dict[str, Any]:
        """Converts the message to the format expected by batch publish."""
        return {"data": self.data, "attributes": self.attributes}

if __name__ == "__main__":
    # Example Usage
    message_data = {"user": {"id": 123, "name": "Test User"}, "action": "created"}
    message_attributes = {"source": "web_app", "event_type": "user_event"}

    # Create a message
    message = PubSubMessage(message_data, message_attributes)
    print(f"Created message: {message}")

    # Convert to JSON and back
    json_bytes = message.to_json()
    print(f"Message as JSON bytes: {json_bytes}")

    decoded_message = PubSubMessage.from_json(json_bytes, message_attributes, "test-message-id-1")
    print(f"Decoded message: {decoded_message}")

    # Create a batch message
    batch_msg = PubSubBatchMessage(message_data, message_attributes)
    print(f"Batch message for publish: {batch_msg.to_publish_format()}")
